/**
 * Test support (Phase 9, Workflow 9B; `analytics-logic`): a seeded generator, so every synthetic
 * population of the analytics tests is the same on every run (rule 9: generated by code from a fixed
 * seed). Not exported from the package root.
 */

/** mulberry32: a small 32-bit generator; `next()` answers a float in [0, 1). */
export interface SeededRandom {
  next(): number;
  /** An integer from `low` to `high`, both included. */
  int(low: number, high: number): number;
  /** One item of `items`. */
  pick<Item>(items: readonly Item[]): Item;
  /** True with probability `p`. */
  chance(p: number): boolean;
}

export function seededRandom(seed: number): SeededRandom {
  let state = seed >>> 0;
  const next = () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let mixed = state;
    mixed = Math.imul(mixed ^ (mixed >>> 15), mixed | 1);
    mixed ^= mixed + Math.imul(mixed ^ (mixed >>> 7), mixed | 61);
    return ((mixed ^ (mixed >>> 14)) >>> 0) / 4294967296;
  };
  const int = (low: number, high: number) => low + Math.floor(next() * (high - low + 1));
  return {
    next,
    int,
    pick: <Item>(items: readonly Item[]): Item => {
      const item = items[int(0, items.length - 1)];
      if (item === undefined) {
        throw new RangeError('pick needs at least one item');
      }
      return item;
    },
    chance: (p: number) => next() < p,
  };
}

/** CPU time of a run in milliseconds, never the wall clock (rule 6). */
export function cpuMilliseconds(run: () => void): number {
  const before = process.cpuUsage();
  run();
  const used = process.cpuUsage(before);
  return (used.user + used.system) / 1000;
}
